ide.base:
/* Isolated adaptation layer for ide. No other theme selectors are allowed here. */
body[data-interface-style="ide"] {
    color: var(--json-tool-text);
    background: var(--json-tool-bg);
    --theme-on-accent: #ffffff;
}
body[data-interface-style="ide"].json-tool-theme-dark { --theme-on-accent: #17202e; }
body[data-interface-style="ide"] :is(.el-dialog, .el-message-box, .el-popper, .el-notification, .el-message) {
    background: var(--json-tool-surface) !important;
    color: var(--json-tool-text) !important;
    border-color: var(--json-tool-border) !important;
    border-radius: var(--theme-radius);
    --el-bg-color-overlay: var(--json-tool-surface);
    --el-fill-color-blank: var(--json-tool-surface);
    --el-fill-color-light: var(--json-tool-surface-soft);
    --el-text-color-primary: var(--json-tool-text);
    --el-text-color-regular: var(--json-tool-text);
    --el-text-color-secondary: var(--json-tool-text-muted);
    --el-border-color: var(--json-tool-border);
    --el-border-color-light: var(--json-tool-border);
    --el-color-primary: var(--theme-accent);
    --el-color-primary-light-9: var(--theme-selected);
}
body[data-interface-style="ide"] :is(.tool-bar-wrapper, .panel-header, .archive-sidebar-header, .editor-status-bar) {
    background: var(--theme-header) !important;
    border-color: var(--json-tool-border) !important;
    color: var(--json-tool-text) !important;
}
body[data-interface-style="ide"] :is(.el-button, .el-select__wrapper, .el-input__wrapper, .el-textarea__inner) {
    background: var(--json-tool-surface) !important;
    color: var(--json-tool-text) !important;
    border-color: var(--json-tool-border) !important;
    border-radius: var(--theme-radius) !important;
    --el-input-text-color: var(--json-tool-text);
    --el-select-input-color: var(--json-tool-text);
}
body[data-interface-style="ide"] .el-button:not(.is-disabled):hover {
    background: var(--theme-selected) !important; border-color: var(--theme-accent) !important;
}
body[data-interface-style="ide"] .el-button--primary {
    background: var(--theme-accent) !important; color: var(--theme-on-accent) !important;
    border-color: var(--theme-accent) !important;
}
body[data-interface-style="ide"] .el-button--primary:not(.is-disabled):hover {
    background: var(--theme-accent) !important; filter: brightness(1.08);
}
body[data-interface-style="ide"] .el-button.is-disabled { opacity: .5; }
body[data-interface-style="ide"] :is(.el-dialog__title, .el-message-box__title, .dialog-title-with-close, .switch-card-title, .settings-subsection-title, .el-checkbox__label, .el-radio__label, .el-select__selected-item, .el-dropdown-menu__item) { color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] :is(.switch-card-desc, .el-dialog__body, .el-message-box__content) { color: var(--json-tool-text-muted) !important; }
body[data-interface-style="ide"] :is(.el-collapse-item__header, .el-collapse-item__wrap, .el-collapse-item__content, .switch-card, .el-dropdown-menu) {
    background: var(--json-tool-surface) !important;
    color: var(--json-tool-text) !important;
    border-color: var(--json-tool-border) !important;
}
body[data-interface-style="ide"] :is(.switch-card:hover, .el-collapse-item__header:hover, .el-dropdown-menu__item:hover, .el-select-dropdown__item.is-hovering) { background: var(--theme-selected) !important; }

/* Feedback keeps data semantics while following the theme surface. */
body[data-interface-style="ide"] .el-message.el-message { background-color: var(--json-tool-surface) !important; border-color: var(--json-tool-border) !important; }
body[data-interface-style="ide"] .el-message.el-message--success { --el-message-bg-color: color-mix(in srgb, var(--theme-success) 14%, var(--json-tool-surface)); --el-message-text-color: var(--theme-success); background-color: var(--el-message-bg-color) !important; border-color: color-mix(in srgb, var(--theme-success) 40%, var(--json-tool-border)) !important; }
body[data-interface-style="ide"] .el-message--success .el-message__content { color: var(--theme-success) !important; }
body[data-interface-style="ide"] .el-message.el-message--warning { --el-message-bg-color: color-mix(in srgb, var(--theme-warning) 16%, var(--json-tool-surface)); --el-message-text-color: var(--theme-warning); background-color: var(--el-message-bg-color) !important; border-color: color-mix(in srgb, var(--theme-warning) 40%, var(--json-tool-border)) !important; }
body[data-interface-style="ide"] .el-message--warning .el-message__content { color: var(--theme-warning) !important; }
body[data-interface-style="ide"] .el-message.el-message--error { --el-message-bg-color: color-mix(in srgb, var(--theme-danger) 14%, var(--json-tool-surface)); --el-message-text-color: var(--theme-danger); background-color: var(--el-message-bg-color) !important; border-color: color-mix(in srgb, var(--theme-danger) 40%, var(--json-tool-border)) !important; }
body[data-interface-style="ide"] .el-message--error .el-message__content { color: var(--theme-danger) !important; }
body[data-interface-style="ide"] .el-message.el-message--info { --el-message-bg-color: var(--json-tool-surface); --el-message-text-color: var(--json-tool-text-muted); }
body[data-interface-style="ide"] .el-message--info .el-message__content { color: var(--json-tool-text-muted) !important; }

/* First-use guide follows theme surfaces in dark mode. */
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide {
    background:
        radial-gradient(circle at 50% 42%, color-mix(in srgb, var(--theme-accent) 12%, transparent), transparent 34%),
        linear-gradient(180deg, color-mix(in srgb, var(--json-tool-surface) 78%, transparent), color-mix(in srgb, var(--json-tool-surface) 54%, transparent));
}
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide-card {
    border-color: var(--json-tool-border);
    background: var(--json-tool-surface-raised);
    box-shadow: var(--ide-dialog-shadow);
}
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide-title { color: var(--json-tool-text); }
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide-desc { color: var(--json-tool-text-muted); }
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide-skip {
    color: var(--json-tool-text);
    border-color: var(--json-tool-border);
    background: var(--json-tool-surface);
}
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide-skip:hover,
body[data-interface-style="ide"] .json-tool-root.theme-dark .first-use-guide-skip:focus-visible { color: var(--theme-accent); border-color: var(--theme-accent); background: var(--theme-selected); }

@media (prefers-reduced-motion: reduce) {
    body[data-interface-style="ide"] :is(.json-tool-root, .json-tool-container, .el-button, .appearance-style-card) { transition: none !important; }
}
body[data-interface-style="ide"] .el-button-group > .el-button { border-radius: 0 !important; }
body[data-interface-style="ide"] .el-button-group > .el-button:first-child { border-radius: var(--theme-radius) 0 0 var(--theme-radius) !important; }
body[data-interface-style="ide"] .el-button-group > .el-button:last-child { border-radius: 0 var(--theme-radius) var(--theme-radius) 0 !important; }

/* Teleported poppers and the demo guide follow the theme surface in dark mode. */
body[data-interface-style="ide"].json-tool-theme-dark .el-popper__arrow::before {
    background: var(--json-tool-surface) !important;
    border-color: var(--json-tool-border) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover.el-popover {
    background: var(--json-tool-surface) !important;
    border-color: var(--json-tool-border) !important;
    color: var(--json-tool-text) !important;
    box-shadow: var(--ide-popover-shadow) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover .el-popper__arrow::before {
    background: var(--json-tool-surface) !important;
    border-color: var(--json-tool-border) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover .demo-guide-header {
    background: var(--json-tool-surface-header) !important;
    border-bottom-color: var(--json-tool-border) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover :is(.demo-guide-header h3, .demo-current-settings strong, .demo-settings-label) {
    color: var(--json-tool-text) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover :is(.demo-guide-content p, .demo-current-settings, .step-dot) {
    color: var(--json-tool-text-muted) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover .demo-current-settings code {
    background: var(--json-tool-surface-soft) !important;
    color: var(--json-tool-text) !important;
}
body[data-interface-style="ide"].json-tool-theme-dark .demo-guide-popover .demo-guide-footer {
    border-top-color: var(--json-tool-border) !important;
}

/* IDE: crisp functional separators; shape, not font metrics, carries density. */
body[data-interface-style="ide"] :is(.json-tool-container, .editor-panel, .tool-bar-wrapper, .panel-header, .archive-sidebar-header, .editor-status-bar) {
    box-shadow: none;
}

/* A real bottom edge separates the flat workbench from surrounding page content.
   Include it in the existing height, including fullscreen and Diff layouts. */
body[data-interface-style="ide"] .json-tool-container {
    box-sizing: border-box;
    border-bottom: 1px solid var(--json-tool-border);
}

/* Floating menus sit just above the flat workbench; modal cards rise one step higher. */
body[data-interface-style="ide"] :is(.el-popper, .el-popover, .el-select__popper, .el-dropdown__popper, .el-message, .el-notification) {
    box-shadow: var(--ide-popover-shadow) !important;
}
body[data-interface-style="ide"] :is(.el-dialog, .el-message-box, .first-use-guide-card, .review-invitation) {
    box-shadow: var(--ide-dialog-shadow) !important;
}
/* Element dialogs and message boxes have no real border. An inset contour keeps their existing geometry. */
body[data-interface-style="ide"] :is(.el-dialog, .el-message-box) {
    box-shadow: inset 0 0 0 1px var(--json-tool-border), var(--ide-dialog-shadow) !important;
}
body[data-interface-style="ide"] .editor-status-bar { font-variant-numeric: tabular-nums; }

/* Settings remain on the dialog plane; drag feedback is a temporary floating hint. */
body[data-interface-style="ide"] .switch-card {
    box-shadow: none !important;
}
body[data-interface-style="ide"] .editor-drag-upload-card {
    box-shadow: var(--ide-popover-shadow);
}

ide.controls:
/* Professional IDE: editor chrome is neutral; color is reserved for actions and state.
   All colors are owned by ideTokens.ts. Geometry and JSON behavior are shared. */
body[data-interface-style="ide"] :is(.el-button.el-button, .archive-header-action, .diff-nav-action, .diff-sync-btn, .panel-action, .first-use-guide-skip, .demo-close-btn, .dialog-close-btn) {
    --ide-action-bg: var(--ide-button); --ide-action-fg: var(--json-tool-text); --ide-action-border: var(--ide-control-border);
    --ide-action-hover: var(--ide-hover); --ide-action-pressed: var(--ide-pressed);
    background: var(--ide-action-bg) !important; color: var(--ide-action-fg) !important; border-color: var(--ide-action-border) !important;
    box-shadow: none !important; filter: none !important;
}
body[data-interface-style="ide"] .el-button.el-button--primary {
    --ide-action-bg: var(--ide-primary); --ide-action-fg: var(--ide-on-primary); --ide-action-border: var(--ide-primary);
    --ide-action-hover: var(--ide-primary-hover); --ide-action-pressed: var(--ide-primary-pressed);
}
body[data-interface-style="ide"] .tool-bar .el-button.el-button--primary,
body[data-interface-style="ide"] .panel-actions .el-button.el-button--primary,
body[data-interface-style="ide"] .el-button.transfer-button {
    --ide-action-bg: var(--theme-header); --ide-action-fg: var(--json-tool-text); --ide-action-border: var(--json-tool-border);
    --ide-action-hover: var(--ide-hover); --ide-action-pressed: var(--ide-pressed);
}
body[data-interface-style="ide"] :is(.el-button.el-button--danger, .archive-header-action.danger) {
    --ide-action-fg: var(--theme-danger); --ide-action-hover: var(--ide-danger-background); --ide-action-pressed: var(--ide-danger-background);
}
body[data-interface-style="ide"] :is(.el-button.el-button, .archive-header-action, .diff-nav-action, .diff-sync-btn, .panel-action, .first-use-guide-skip, .demo-close-btn, .dialog-close-btn):hover:not(:disabled):not(.is-disabled) { background: var(--ide-action-hover) !important; }
body[data-interface-style="ide"] :is(.el-button.el-button, .archive-header-action, .diff-nav-action, .diff-sync-btn, .panel-action, .first-use-guide-skip, .demo-close-btn, .dialog-close-btn):active:not(:disabled):not(.is-disabled) { background: var(--ide-action-pressed) !important; }
body[data-interface-style="ide"] :is(.el-button.el-button.is-disabled, .el-button:disabled, .archive-header-action:disabled, .diff-nav-action:disabled, .diff-sync-btn:disabled, .panel-action:disabled) {
    background: var(--ide-disabled-background) !important; color: var(--ide-disabled) !important; border-color: var(--ide-disabled-border) !important; opacity: 1 !important;
}
/* Toolbar utility buttons keep one neutral frame at rest and on pointer interaction. */
body[data-interface-style="ide"] .tool-bar .el-button:is(.settings-tool-button, .fullscreen-btn):not(:disabled):not(.is-disabled) {
    border-color: var(--ide-action-border) !important;
}
body[data-interface-style="ide"] :is(button, [role="button"]):focus-visible { outline: 1px solid var(--ide-focus) !important; outline-offset: 2px; }
body[data-interface-style="ide"] .transfer-button svg { color: inherit !important; }
body[data-interface-style="ide"] .resizer::after { background: var(--ide-control-border); }
body[data-interface-style="ide"] .main-action-group > .data-convert-dropdown:not(:first-child) .el-button { margin-left: 0 !important; border-left: 1px solid var(--json-tool-border) !important; }

/* Inputs use one quiet frame, not Element Plus's colored success/primary categories. */
body[data-interface-style="ide"] :is(.el-select__wrapper.el-select__wrapper, .el-input__wrapper.el-input__wrapper, .el-textarea__inner) {
    background: var(--ide-input) !important; color: var(--json-tool-text) !important;
    box-shadow: inset 0 0 0 1px var(--ide-control-border) !important; border: 0 !important;
}
body[data-interface-style="ide"] :is(.el-select__wrapper.is-focused, .el-input__wrapper.is-focus, .el-textarea__inner:focus) { box-shadow: inset 0 0 0 1px var(--ide-focus) !important; }
body[data-interface-style="ide"] :is(.el-input__inner, .el-textarea__inner)::placeholder { color: var(--json-tool-text-muted) !important; }
body[data-interface-style="ide"] :is(.el-select__placeholder, .el-select__selected-item, .el-select__caret) { color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] :is(.el-select-dropdown__item.is-selected, .el-select-dropdown__item.is-hovering, .el-dropdown-menu__item:hover, .el-autocomplete-suggestion li:is(:hover, .highlighted)) { background: var(--theme-selected) !important; color: var(--ide-on-selected) !important; }
body[data-interface-style="ide"] .el-autocomplete-suggestion li:is(:hover, .highlighted) :is(.path-text, .path-type) { color: var(--ide-on-selected) !important; }
body[data-interface-style="ide"] .el-radio.is-checked .el-radio__label { color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] .el-checkbox__inner { background: var(--ide-input); border-color: var(--ide-control-border); }
body[data-interface-style="ide"] :is(.el-checkbox__input.is-checked, .el-checkbox__input.is-indeterminate) .el-checkbox__inner { background: var(--ide-primary); border-color: var(--ide-primary); }
body[data-interface-style="ide"] .el-checkbox__input.is-checked .el-checkbox__inner::after { border-color: var(--ide-on-primary); }
body[data-interface-style="ide"] .el-checkbox__input.is-indeterminate .el-checkbox__inner::before { background: var(--ide-on-primary); }
body[data-interface-style="ide"] .appearance-mode button[aria-pressed="true"] { color: var(--ide-on-selected); background: var(--theme-selected); border-color: var(--ide-focus); }

/* Settings choice tiles own their selected surface, not the legacy light-blue fill.
   Language, font size, indent and sort direction all share this contract. */
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio.is-bordered {
    background: var(--ide-button); border-color: var(--ide-control-border); border-radius: var(--theme-radius);
    color: var(--json-tool-text);
}
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio__label { color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio.is-bordered:not(.is-disabled):not(.is-checked):hover { background: var(--ide-hover); }
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio.is-bordered.is-checked {
    background: var(--theme-selected); border-color: var(--theme-accent);
}
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio.is-bordered.is-checked .el-radio__label { color: var(--ide-on-selected) !important; }
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio:has(input:focus-visible) { outline: 1px solid var(--theme-accent); outline-offset: 2px; }
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio.is-bordered.is-disabled { background: var(--ide-disabled-background); border-color: var(--ide-disabled-border); }
body[data-interface-style="ide"] .el-dialog.settings-dialog-wrapper .switch-card-radio-group .el-radio.is-bordered.is-disabled .el-radio__label { color: var(--ide-disabled) !important; }
body[data-interface-style="ide"] .el-checkbox__input:not(.is-disabled):has(input:focus-visible) .el-checkbox__inner { outline: 1px solid var(--theme-accent); outline-offset: 2px; }
body[data-interface-style="ide"] .el-checkbox__input.is-disabled .el-checkbox__inner::after { border-color: var(--ide-disabled); }
body[data-interface-style="ide"] .el-checkbox__input.is-disabled .el-checkbox__inner::before { background: var(--ide-disabled); }

/* One rounded frame clips the square child fills, keeping all four corners continuous. */
body[data-interface-style="ide"] .json-tool-root .collapse-control { height: 32px; box-sizing: border-box; gap: 0; background: var(--ide-input); border: 1px solid var(--ide-control-border); border-radius: var(--theme-radius); overflow: hidden; }
body[data-interface-style="ide"] .json-tool-root .collapse-control :is(.el-select__wrapper, .el-input__wrapper, .el-button.level-action-button) { height: 30px; min-height: 30px; box-sizing: border-box; margin: 0 !important; background: var(--ide-input) !important; color: var(--json-tool-text) !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; }
body[data-interface-style="ide"] .json-tool-root .collapse-control .level-action-button::before { content: ""; position: absolute; left: 0; top: 7px; bottom: 7px; width: 1px; background: var(--ide-control-border); opacity: .6; pointer-events: none; }
body[data-interface-style="ide"] .json-tool-root .collapse-control :is(.el-select__wrapper:not(.is-disabled):hover, .level-action-button:not(:disabled):hover) { background: var(--ide-hover) !important; }
body[data-interface-style="ide"] .json-tool-root .collapse-control:has(.el-select__wrapper.is-disabled) { background: var(--ide-disabled-background); border-color: var(--ide-disabled-border); }
body[data-interface-style="ide"] .json-tool-root .collapse-control :is(.el-select__wrapper.is-disabled, .level-action-button:disabled) { background: var(--ide-disabled-background) !important; color: var(--ide-disabled) !important; }
body[data-interface-style="ide"] .collapse-control .level-select:has(.is-disabled) :is(.el-select__selected-item, .el-select__caret) { color: var(--ide-disabled) !important; }

/* Editor, panel chrome and dialogs share neutral surfaces, without blue panels. */
body[data-interface-style="ide"] .panel-header { box-shadow: none !important; }
body[data-interface-style="ide"] .panel-title { font-weight: 500; color: var(--json-tool-text); }
body[data-interface-style="ide"] .monaco-editor .margin { background: var(--json-tool-gutter-bg) !important; }
body[data-interface-style="ide"] :is(.el-dialog.el-dialog .el-dialog__header, .el-message-box.el-message-box .el-message-box__header) { background: var(--theme-header) !important; border-color: var(--json-tool-border) !important; }
body[data-interface-style="ide"] :is(.el-dialog__footer, .dialog-footer, .el-message-box__btns) { border-color: var(--json-tool-border) !important; }
body[data-interface-style="ide"] :is(.dialog-title, .section-title, .rule-name-label, .field-path-label, .field-label, .saved-rule-name, .affix-row-label, .affix-section-title, .form-value-text, .form-compact-line, .path-help-content) { color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] :is(.priority-hint, .saved-rule-meta, .affix-hint, .switch-card-desc) { color: var(--json-tool-text-muted) !important; }
body[data-interface-style="ide"] .el-dialog :is(.rule-item, .field-path-item, .saved-rule-item, .affix-section, .form-value-quote--compact) { background: var(--json-tool-surface-soft) !important; border-color: var(--json-tool-border) !important; }
body[data-interface-style="ide"] :is(.field-path-priority, .path-help-content code) { background: var(--ide-code) !important; color: var(--json-tool-text) !important; border-color: var(--json-tool-border) !important; }
body[data-interface-style="ide"] .path-help-panel { background: var(--json-tool-surface-soft); border-left-color: var(--theme-accent); }
body[data-interface-style="ide"] .el-dialog .el-alert { background: var(--json-tool-surface-soft) !important; border-color: var(--json-tool-border) !important; color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] .el-alert :is(.el-alert__title, .el-alert__description, .el-alert__icon) { color: var(--json-tool-text) !important; }
body[data-interface-style="ide"] .el-message.el-message { border-color: var(--json-tool-border) !important; }
body[data-interface-style="ide"] .el-message.el-message--success { --el-message-bg-color: var(--ide-success-background); --el-message-text-color: var(--theme-success); }
body[data-interface-style="ide"] .el-message.el-message--warning { --el-message-bg-color: var(--ide-warning-background); --el-message-text-color: var(--theme-warning); }
body[data-interface-style="ide"] .el-message.el-message--error { --el-message-bg-color: var(--ide-danger-background); --el-message-text-color: var(--theme-danger); }
body[data-interface-style="ide"] .el-message .el-message__content { color: var(--el-message-text-color) !important; }
body[data-interface-style="ide"] .el-message.el-message { background: var(--el-message-bg-color) !important; }
body[data-interface-style="ide"] .el-dialog :is(.delete-warning-icon, .delete-confirm-text, .add-field-path-error) { color: var(--theme-danger) !important; }
body[data-interface-style="ide"] .delete-confirm { background: var(--ide-danger-background); border-color: var(--theme-danger); }
